<script type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"ProfessionalService","@id":"https://southcarolinainsuranceappraiser.com/#business","name":"South Carolina Insurance Appraiser","url":"https://southcarolinainsuranceappraiser.com/","telephone":"+1 (844) 537-1427","email":"info@southcarolinainsuranceappraiser.com","logo":{"@type":"ImageObject","@id":"https://southcarolinainsuranceappraiser.com/#logo","url":"https://southcarolinainsuranceappraiser.com/favicon-512.png","width":512,"height":512,"caption":"South Carolina Insurance Appraiser"},"image":{"@id":"https://southcarolinainsuranceappraiser.com/#logo"},"address":{"@type":"PostalAddress","addressRegion":"SC","addressCountry":"US"},"contactPoint":[{"@type":"ContactPoint","telephone":"+1 (844) 537-1427","email":"info@southcarolinainsuranceappraiser.com","contactType":"customer service","areaServed":"US-SC","availableLanguage":"en"}],"description":"Independent insurance appraisal, estimate review and umpire services for disputed property claims across all 46 South Carolina counties.","areaServed":[{"@type":"State","name":"South Carolina"},{"@type":"City","name":"Charleston"},{"@type":"City","name":"Columbia"},{"@type":"City","name":"Greenville"},{"@type":"City","name":"Myrtle Beach"},{"@type":"City","name":"Spartanburg"},{"@type":"City","name":"Mount Pleasant"},{"@type":"City","name":"Summerville"},{"@type":"City","name":"Rock Hill"},{"@type":"City","name":"Hilton Head Island"},{"@type":"City","name":"Florence"},{"@type":"City","name":"Beaufort"},{"@type":"City","name":"Aiken"}],"hasOfferCatalog":{"@type":"OfferCatalog","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Demand Representation","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/appraisal-demand-representation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Home Insurance Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/home-insurance-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/commercial-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/roof-hail-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wind & Tornado Claim Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/wind-tornado-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Hurricane Claim Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/hurricane-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Claim Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/water-damage-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/fire-smoke-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tree Fall & Ice Storm Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/tree-fall-ice-storm-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Earthquake Claim Appraisal","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/earthquake-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Claim Estimate Review","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/claim-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire & Neutral Appraiser","url":"https://southcarolinainsuranceappraiser.com/claim-dispute-services/umpire-neutral-appraiser/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Hurricane claims","Wind and flood causation","Xactimate estimating","Umpire services"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://southcarolinainsuranceappraiser.com/#website","url":"https://southcarolinainsuranceappraiser.com/","name":"South Carolina Insurance Appraiser","publisher":{"@id":"https://southcarolinainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://southcarolinainsuranceappraiser.com/appraisal-glossary/#webpage","url":"https://southcarolinainsuranceappraiser.com/appraisal-glossary/","name":"Insurance Appraisal Glossary: ACV, Umpire, SCWHUA & More","description":"Insurance appraisal glossary: plain-English definitions of ACV, replacement cost, holdback, umpire, hurricane deductible, SCWHUA and more.","inLanguage":"en-US","isPartOf":{"@id":"https://southcarolinainsuranceappraiser.com/#website"},"about":{"@id":"https://southcarolinainsuranceappraiser.com/#business"},"publisher":{"@id":"https://southcarolinainsuranceappraiser.com/#business"},"dateModified":"2026-11-12","primaryImageOfPage":{"@id":"https://southcarolinainsuranceappraiser.com/appraisal-glossary/#primaryimage"},"breadcrumb":{"@id":"https://southcarolinainsuranceappraiser.com/appraisal-glossary/#breadcrumb"},"mainEntity":{"@id":"https://southcarolinainsuranceappraiser.com/appraisal-glossary/#definedtermset"}},{"@type":"ImageObject","@id":"https://southcarolinainsuranceappraiser.com/appraisal-glossary/#primaryimage","url":"https://southcarolinainsuranceappraiser.com/assets/img/photos/calculator.webp","width":1200,"height":800,"caption":"Scientific calculator resting on printed paperwork"},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://southcarolinainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal glossary","item":"https://southcarolinainsuranceappraiser.com/appraisal-glossary/"}],"@id":"https://southcarolinainsuranceappraiser.com/appraisal-glossary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Insurance appraisal glossary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"The replacement cost of damaged property minus depreciation for age and wear. Many policies pay ACV first and the balance after repairs are finished."},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"The increase in your normal living costs, such as a rental or hotel and extra meals, while a covered loss leaves your home unlivable. It is usually paid under Coverage D."},{"@type":"DefinedTerm","name":"Anti-concurrent causation","description":"Policy wording that excludes a loss caused by an excluded peril, such as flood, even if a covered peril, such as wind, contributed at the same time. Courts read these clauses differently, so legal advice matters when one is in play."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision that sets the amount of loss, signed by at least two of the three panel members. It is generally binding on the amount but not on coverage questions."},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy provision that lets either party demand appraisal when they agree a loss is covered but disagree on its amount. It sets out how appraisers and the umpire are chosen."},{"@type":"DefinedTerm","name":"Appraiser","description":"The person each side chooses to value the loss during appraisal. Most policies require the appraiser to be competent and disinterested."},{"@type":"DefinedTerm","name":"Catastrophe savings account","description":"A tax-advantaged savings account created by South Carolina’s 2007 coastal insurance reforms. Homeowners can use it to set money aside for a hurricane deductible or other uninsured storm losses."},{"@type":"DefinedTerm","name":"Coinsurance","description":"A clause, common in commercial policies, that reduces a claim payment if the property was insured for less than a required percentage of its value. The shortfall is shared by the policyholder."},{"@type":"DefinedTerm","name":"Coverage A (dwelling)","description":"The part of a homeowners policy that covers the house itself and attached structures. Its limit is often the base for percentage hurricane deductibles."},{"@type":"DefinedTerm","name":"Coverage B (other structures)","description":"Coverage for detached structures on the property, such as fences, sheds and detached garages. Its limit is usually a percentage of Coverage A."},{"@type":"DefinedTerm","name":"Coverage C (personal property)","description":"Coverage for belongings such as furniture, clothing and electronics. It may pay actual cash value or replacement cost depending on the policy."},{"@type":"DefinedTerm","name":"Coverage D (loss of use)","description":"Coverage for additional living expense or lost rental income when a covered loss makes the home unlivable. It is often limited by dollars or time."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing the insured, the property, coverage limits, deductibles and endorsements. In South Carolina, hurricane deductibles must be clearly disclosed on it."},{"@type":"DefinedTerm","name":"Deductible","description":"The portion of a covered loss the policyholder pays before the insurer pays. It may be a flat dollar amount or a percentage of the dwelling limit."},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value of property due to age, wear and condition. It is the difference between replacement cost and actual cash value."},{"@type":"DefinedTerm","name":"Earthquake endorsement","description":"An add-on that brings earthquake damage into a policy that otherwise excludes it. It usually carries its own, often large, percentage deductible."},{"@type":"DefinedTerm","name":"Endorsement","description":"A written change to a policy that adds, removes or modifies coverage. Endorsements control over the base policy wording where they conflict."},{"@type":"DefinedTerm","name":"Hurricane deductible","description":"A separate deductible that applies to losses from a hurricane, often a percentage of the dwelling limit. The policy’s trigger wording defines when it applies instead of the standard deductible."},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether undamaged materials must be replaced so repairs match in color, texture and appearance. Policy wording and the availability of materials drive these disputes."},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to protect property from further damage after a loss, such as tarping a roof or drying a wet room. Most policies require it and pay reasonable mitigation costs."},{"@type":"DefinedTerm","name":"Mortgagee clause","description":"A policy provision that protects the mortgage lender’s interest in the property. It is why lenders are often named on claim checks."},{"@type":"DefinedTerm","name":"Named storm","description":"A tropical storm or hurricane that has been given a name by the National Hurricane Center. Some policies use a named-storm deductible triggered by any such storm, not only hurricanes."},{"@type":"DefinedTerm","name":"National Flood Insurance Program (NFIP)","description":"The federal program that writes most flood insurance in the United States. Its standard flood policy has its own rules, deadlines and appraisal provision."},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for the extra cost of meeting current building codes when damaged property is repaired or rebuilt. It is often limited to a percentage of the dwelling limit."},{"@type":"DefinedTerm","name":"Overhead and profit","description":"The general contractor’s charge for managing and coordinating a job, often estimated at 10% overhead plus 10% profit. It is a frequent dispute when a repair involves several trades."},{"@type":"DefinedTerm","name":"Peril","description":"A cause of loss, such as wind, hail, fire, lightning or theft. Policies either list covered perils or cover all perils except those excluded."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed and supporting details. Some policies, including the NFIP flood policy, require it within a set time."},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation held back from an initial replacement cost claim payment that can be recovered once repairs or replacement are completed. Time limits often apply."},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without deducting depreciation."},{"@type":"DefinedTerm","name":"Reservation of rights","description":"A letter in which the insurer says it is handling a claim while reserving the right to deny coverage later. It signals a possible coverage issue worth reviewing carefully."},{"@type":"DefinedTerm","name":"SC Safe Home","description":"A South Carolina grant program, created under the 2007 coastal insurance reforms, that helps eligible homeowners pay for wind-resistance upgrades such as roof-to-wall connections and opening protection."},{"@type":"DefinedTerm","name":"Scope of loss","description":"The list of damaged items and the repair work each one needs. Most appraisal disputes start with differences in scope rather than in unit prices."},{"@type":"DefinedTerm","name":"South Carolina Department of Insurance (SCDOI)","description":"The state agency that regulates insurers, licenses adjusters and handles consumer complaints. It does not decide the value of individual claims."},{"@type":"DefinedTerm","name":"South Carolina Wind and Hail Underwriting Association (SCWHUA)","description":"The insurer of last resort for wind and hail coverage in designated coastal areas of South Carolina. Its wind-only policies are often paired with a homeowners policy that excludes wind."},{"@type":"DefinedTerm","name":"Square (roofing)","description":"A unit of roof area equal to 100 square feet. Roofing estimates are priced per square, plus a waste factor."},{"@type":"DefinedTerm","name":"Steep charge","description":"An added labor charge for working on steep roof slopes, commonly applied at about a 7/12 pitch and steeper. It is a frequent line-item dispute in roof estimates."},{"@type":"DefinedTerm","name":"Storm surge","description":"Seawater pushed ashore by a hurricane or tropical storm. Damage from surge is treated as flood and is excluded from standard homeowners and wind policies."},{"@type":"DefinedTerm","name":"Subrogation","description":"The insurer’s right, after paying a claim, to pursue a third party who caused the loss. Policyholders must not waive that right without the insurer’s consent."},{"@type":"DefinedTerm","name":"Suit limitation","description":"The time limit for filing a lawsuit over a claim, set by the policy, by statute or both. Confirm the deadline that applies with a South Carolina attorney."},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add items or costs to an insurer’s estimate, often after hidden damage is found during repairs. Many disputes resolve through supplements without appraisal."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides only the items the two appraisers cannot resolve. Agreement by any two panel members sets the award."},{"@type":"DefinedTerm","name":"Wind-driven rain","description":"Rain forced into a building by high wind. Many policies cover interior water damage only if wind first creates an opening in the roof or walls."},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers, adjusters and contractors to price repairs with regional cost data. Appraisers often build or compare estimates in it."}],"@id":"https://southcarolinainsuranceappraiser.com/appraisal-glossary/#definedtermset"}]}</script>
</head>
